<?php
if (!defined('ABSPATH')) exit;

/* FormPilot 10 advanced scheduling subsystems. */
function fp_adv_tables(){ global $wpdb; return [
    'booking_hosts'=>$wpdb->prefix.'fp_booking_hosts',
    'workflow_jobs'=>$wpdb->prefix.'fp_workflow_jobs',
    'integrations'=>$wpdb->prefix.'fp_integrations',
    'invoices'=>$wpdb->prefix.'fp_invoices',
    'api_keys'=>$wpdb->prefix.'fp_api_keys',
    'webhook_deliveries'=>$wpdb->prefix.'fp_webhook_deliveries',
    'recurring_rules'=>$wpdb->prefix.'fp_recurring_rules',
]; }
function fp_adv_column($table,$column,$definition){ global $wpdb; $exists=$wpdb->get_var($wpdb->prepare("SHOW COLUMNS FROM {$table} LIKE %s",$column)); if(!$exists)$wpdb->query("ALTER TABLE {$table} ADD {$column} {$definition}"); }
function fp_adv_install(){
    global $wpdb; require_once ABSPATH.'wp-admin/includes/upgrade.php'; $c=$wpdb->get_charset_collate(); $a=fp_adv_tables(); $t=fp_sched_tables();
    dbDelta("CREATE TABLE {$a['booking_hosts']} (id bigint unsigned NOT NULL AUTO_INCREMENT, booking_id bigint unsigned NOT NULL, user_id bigint unsigned NOT NULL, role varchar(30) NOT NULL DEFAULT 'host', created_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY booking_user(booking_id,user_id), KEY user_id(user_id)) {$c};");
    dbDelta("CREATE TABLE {$a['workflow_jobs']} (id bigint unsigned NOT NULL AUTO_INCREMENT, workflow_id bigint unsigned NOT NULL, booking_id bigint unsigned NOT NULL DEFAULT 0, event_key varchar(80) NOT NULL, due_at datetime NOT NULL, status varchar(20) NOT NULL DEFAULT 'queued', attempts tinyint unsigned NOT NULL DEFAULT 0, last_error text NULL, locked_at datetime NULL, created_at datetime NOT NULL, completed_at datetime NULL, PRIMARY KEY(id), KEY due_status(status,due_at), KEY booking_id(booking_id)) {$c};");
    dbDelta("CREATE TABLE {$a['integrations']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, provider varchar(40) NOT NULL, label varchar(190) NOT NULL DEFAULT '', config longtext NULL, active tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, updated_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY user_provider(user_id,provider)) {$c};");
    dbDelta("CREATE TABLE {$a['invoices']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, booking_id bigint unsigned NOT NULL, invoice_number varchar(80) NOT NULL, public_token varchar(64) NOT NULL, currency varchar(8) NOT NULL DEFAULT 'USD', subtotal decimal(12,2) NOT NULL DEFAULT 0, tax decimal(12,2) NOT NULL DEFAULT 0, total decimal(12,2) NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT 'open', payment_reference varchar(190) NOT NULL DEFAULT '', issued_at datetime NOT NULL, paid_at datetime NULL, PRIMARY KEY(id), UNIQUE KEY invoice_number(invoice_number), UNIQUE KEY public_token(public_token), KEY booking_id(booking_id)) {$c};");
    dbDelta("CREATE TABLE {$a['api_keys']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, name varchar(190) NOT NULL, key_prefix varchar(20) NOT NULL, key_hash char(64) NOT NULL, scopes longtext NULL, active tinyint(1) NOT NULL DEFAULT 1, last_used_at datetime NULL, created_at datetime NOT NULL, PRIMARY KEY(id), UNIQUE KEY key_hash(key_hash), KEY user_id(user_id)) {$c};");
    dbDelta("CREATE TABLE {$a['webhook_deliveries']} (id bigint unsigned NOT NULL AUTO_INCREMENT, webhook_id bigint unsigned NOT NULL, event_key varchar(80) NOT NULL, payload longtext NOT NULL, status varchar(20) NOT NULL DEFAULT 'queued', attempts tinyint unsigned NOT NULL DEFAULT 0, next_attempt_at datetime NOT NULL, response_code smallint unsigned NOT NULL DEFAULT 0, last_error text NULL, created_at datetime NOT NULL, delivered_at datetime NULL, PRIMARY KEY(id), KEY due_status(status,next_attempt_at), KEY webhook_id(webhook_id)) {$c};");
    dbDelta("CREATE TABLE {$a['recurring_rules']} (id bigint unsigned NOT NULL AUTO_INCREMENT, user_id bigint unsigned NOT NULL, event_id bigint unsigned NOT NULL, frequency varchar(20) NOT NULL DEFAULT 'weekly', interval_count smallint unsigned NOT NULL DEFAULT 1, max_occurrences smallint unsigned NOT NULL DEFAULT 6, active tinyint(1) NOT NULL DEFAULT 1, created_at datetime NOT NULL, PRIMARY KEY(id), KEY event_id(event_id)) {$c};");
    fp_adv_column($t['bookings'],'manage_token',"varchar(64) NOT NULL DEFAULT ''");
    fp_adv_column($t['bookings'],'series_key',"varchar(64) NOT NULL DEFAULT ''");
    fp_adv_column($t['bookings'],'source',"varchar(40) NOT NULL DEFAULT 'scheduler'");
    fp_adv_column($t['bookings'],'payment_intent_id',"varchar(190) NOT NULL DEFAULT ''");
    fp_adv_column($t['bookings'],'invoice_id',"bigint unsigned NOT NULL DEFAULT 0");
    fp_adv_column($t['bookings'],'google_event_id',"varchar(190) NOT NULL DEFAULT ''");
    fp_adv_column($t['bookings'],'cancelled_at',"datetime NULL");
}
add_action('admin_init','fp_adv_install');
function fp_adv_maybe_upgrade(){ if(get_option('fp_adv_schema_version')!=='10.0.0'){ fp_adv_install(); update_option('fp_adv_schema_version','10.0.0',false); } }
add_action('plugins_loaded','fp_adv_maybe_upgrade',30);

function fp_adv_manage_token(){ return bin2hex(random_bytes(24)); }
function fp_adv_remote_ip(){ foreach(['HTTP_CF_CONNECTING_IP','HTTP_X_FORWARDED_FOR','REMOTE_ADDR'] as $k){ if(!empty($_SERVER[$k])){ $v=explode(',',sanitize_text_field(wp_unslash($_SERVER[$k]))); return trim($v[0]); } } return 'unknown'; }
function fp_adv_rate_limit($bucket,$limit=30,$window=60){ $key='fp_rl_'.md5($bucket.'|'.fp_adv_remote_ip()); $n=(int)get_transient($key); if($n >= $limit)return false; set_transient($key,$n+1,$window); return true; }
function fp_adv_public_guard($route,$limit=30){ if(!fp_adv_rate_limit($route,$limit,60))return new WP_Error('rate_limited','Too many requests. Please try again shortly.',['status'=>429]); return true; }

/* External busy-time check. Google Calendar is queried live when connected. */
add_filter('fp_sched_host_available',function($available,$host,$start,$end){
    if(!$available) return false;
    if(!function_exists('ssb_google_is_connected') || !ssb_google_is_connected()) return true;
    $owner=(int)get_option('ssb_google_owner_user_id',0); if($owner && (int)$host!==$owner) return true;
    $token=function_exists('ssb_google_get_access_token')?ssb_google_get_access_token():''; if(!$token)return true;
    $calendar=get_option('ssb_google_calendar_id','primary');
    $body=['timeMin'=>gmdate('c',strtotime($start.' UTC')),'timeMax'=>gmdate('c',strtotime($end.' UTC')),'items'=>[['id'=>$calendar]]];
    $r=wp_remote_post('https://www.googleapis.com/calendar/v3/freeBusy',['timeout'=>8,'headers'=>['Authorization'=>'Bearer '.$token,'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);
    if(is_wp_error($r) || wp_remote_retrieve_response_code($r)!==200)return true;
    $x=json_decode(wp_remote_retrieve_body($r),true); return empty($x['calendars'][$calendar]['busy']);
},10,4);

function fp_adv_store_booking_hosts($booking_id,$hosts){ global $wpdb; $a=fp_adv_tables(); foreach(array_unique(array_map('absint',(array)$hosts)) as $uid){ if(!$uid)continue; $wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$a['booking_hosts']} (booking_id,user_id,role,created_at) VALUES (%d,%d,'host',%s)",$booking_id,$uid,fp_sched_now())); $t=fp_sched_tables(); $wpdb->update($t['team_members'],['last_assigned_at'=>fp_sched_now()],['user_id'=>$uid]); } }

/* Durable workflows: queue now, reminders before start, followups after end. */
function fp_adv_enqueue_workflows($booking_id,$event_key){
    if(!fp_sched_feature('workflows'))return; global $wpdb; $t=fp_sched_tables(); $a=fp_adv_tables();
    $b=$wpdb->get_row($wpdb->prepare("SELECT b.*,e.user_id FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d",$booking_id)); if(!$b)return;
    $rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['workflows']} WHERE user_id=%d AND active=1",$b->user_id));
    foreach($rows as $w){ $due=null; if($w->trigger_key===$event_key)$due=time()+max(0,(int)$w->delay_minutes)*60; elseif($event_key==='booking.created' && $w->trigger_key==='booking.before_start')$due=strtotime($b->start_at.' UTC')-max(0,(int)$w->delay_minutes)*60; elseif($event_key==='booking.created' && $w->trigger_key==='booking.after_end')$due=strtotime($b->end_at.' UTC')+max(0,(int)$w->delay_minutes)*60; if(!$due)continue; if($due<time())$due=time(); $exists=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$a['workflow_jobs']} WHERE workflow_id=%d AND booking_id=%d AND event_key=%s AND status IN ('queued','running')",$w->id,$booking_id,$w->trigger_key)); if(!$exists)$wpdb->insert($a['workflow_jobs'],['workflow_id'=>$w->id,'booking_id'=>$booking_id,'event_key'=>$w->trigger_key,'due_at'=>gmdate('Y-m-d H:i:s',$due),'status'=>'queued','created_at'=>fp_sched_now()]); }
}
function fp_adv_render_tokens($text,$b){ $map=['{{invitee_name}}'=>$b->invitee_name,'{{invitee_email}}'=>$b->invitee_email,'{{start_at}}'=>$b->start_at.' UTC','{{event_title}}'=>$b->title,'{{manage_url}}'=>home_url('/?formpilot_manage='.$b->manage_token),'{{location}}'=>$b->location]; return strtr((string)$text,$map); }
function fp_adv_run_workflow_job($job){ global $wpdb; $a=fp_adv_tables(); $t=fp_sched_tables(); $w=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['workflows']} WHERE id=%d",$job->workflow_id)); $b=$wpdb->get_row($wpdb->prepare("SELECT b.*,e.title,e.user_id FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d",$job->booking_id)); if(!$w||!$b)throw new Exception('Workflow or booking missing.'); $d=json_decode($w->action_data,true); $d=is_array($d)?$d:[];
    if($w->action_key==='email'){ $to=fp_adv_render_tokens(!empty($d['email'])?$d['email']:$b->invitee_email,$b); $subject=fp_adv_render_tokens(!empty($d['subject'])?$d['subject']:('Reminder: '.$b->title),$b); $body=fp_adv_render_tokens(!empty($d['body'])?$d['body']:('<p>Hello {{invitee_name}},</p><p>This is a reminder for <strong>{{event_title}}</strong> at {{start_at}}.</p><p>{{location}}</p><p><a href="{{manage_url}}">Manage booking</a></p>'),$b); if(!wp_mail($to,$subject,$body,['Content-Type: text/html; charset=UTF-8']))throw new Exception('Email delivery returned false.'); }
    elseif($w->action_key==='webhook'){ fp_adv_webhook_enqueue('workflow.'.$w->trigger_key,['booking_id'=>(int)$b->id,'workflow_id'=>(int)$w->id]); }
    else throw new Exception('Unsupported workflow action.');
}
function fp_adv_process_jobs(){ global $wpdb; $a=fp_adv_tables(); $jobs=$wpdb->get_results("SELECT * FROM {$a['workflow_jobs']} WHERE status='queued' AND due_at<=UTC_TIMESTAMP() ORDER BY id ASC LIMIT 25"); foreach($jobs as $j){ $wpdb->update($a['workflow_jobs'],['status'=>'running','locked_at'=>fp_sched_now(),'attempts'=>(int)$j->attempts+1],['id'=>$j->id]); try{ fp_adv_run_workflow_job($j); $wpdb->update($a['workflow_jobs'],['status'=>'done','completed_at'=>fp_sched_now(),'last_error'=>null],['id'=>$j->id]); }catch(Throwable $e){ $attempt=(int)$j->attempts+1; $wpdb->update($a['workflow_jobs'],['status'=>$attempt>=5?'failed':'queued','due_at'=>gmdate('Y-m-d H:i:s',time()+min(3600,60*pow(2,$attempt))),'last_error'=>substr($e->getMessage(),0,1000)],['id'=>$j->id]); } } }
add_action('fp_adv_minute','fp_adv_process_jobs');
add_filter('cron_schedules',function($s){$s['fp_minute']=['interval'=>60,'display'=>'Every minute'];return $s;});
add_action('init',function(){if(!wp_next_scheduled('fp_adv_minute'))wp_schedule_event(time()+60,'fp_minute','fp_adv_minute');});
add_action('fp_sched_booking_created',function($id){fp_adv_enqueue_workflows($id,'booking.created');},1);

/* Reliable webhook queue with retry/backoff. */
function fp_adv_webhook_enqueue($event,$payload){ global $wpdb; $t=fp_sched_tables(); $a=fp_adv_tables(); $hooks=$wpdb->get_results("SELECT * FROM {$t['webhooks']} WHERE active=1"); foreach($hooks as $h){$events=json_decode($h->events,true); if(is_array($events)&&$events&&!in_array($event,$events,true))continue; $wpdb->insert($a['webhook_deliveries'],['webhook_id'=>$h->id,'event_key'=>$event,'payload'=>wp_json_encode($payload),'status'=>'queued','next_attempt_at'=>fp_sched_now(),'created_at'=>fp_sched_now()]);}}
function fp_adv_process_webhooks(){ global $wpdb; $t=fp_sched_tables();$a=fp_adv_tables();$rows=$wpdb->get_results("SELECT d.*,w.url,w.secret FROM {$a['webhook_deliveries']} d JOIN {$t['webhooks']} w ON w.id=d.webhook_id WHERE d.status='queued' AND d.next_attempt_at<=UTC_TIMESTAMP() ORDER BY d.id LIMIT 20"); foreach($rows as $d){$envelope=['event'=>$d->event_key,'data'=>json_decode($d->payload,true),'sent_at'=>time(),'delivery_id'=>(int)$d->id];$body=wp_json_encode($envelope);$sig=$d->secret?hash_hmac('sha256',$body,$d->secret):'';$r=wp_remote_post($d->url,['timeout'=>12,'headers'=>['Content-Type'=>'application/json','X-FormPilot-Signature'=>$sig,'X-FormPilot-Delivery'=>(string)$d->id],'body'=>$body]);$attempt=(int)$d->attempts+1;$code=is_wp_error($r)?0:(int)wp_remote_retrieve_response_code($r);if($code>=200&&$code<300)$wpdb->update($a['webhook_deliveries'],['status'=>'delivered','attempts'=>$attempt,'response_code'=>$code,'delivered_at'=>fp_sched_now()],['id'=>$d->id]);else{$err=is_wp_error($r)?$r->get_error_message():'HTTP '.$code;$wpdb->update($a['webhook_deliveries'],['status'=>$attempt>=6?'failed':'queued','attempts'=>$attempt,'response_code'=>$code,'last_error'=>substr($err,0,1000),'next_attempt_at'=>gmdate('Y-m-d H:i:s',time()+min(21600,60*pow(2,$attempt)))],['id'=>$d->id]);}}}
add_action('fp_adv_minute','fp_adv_process_webhooks');

/* Stripe for paid event types. Booking is only accepted after a verified successful PaymentIntent. */
function fp_adv_event_price($event){$s=fp_sched_event_settings($event);return max(0,(float)($s['price']??0));}
function fp_adv_stripe_secret(){return trim((string)get_option('ssb_stripe_secret_key',''));}
function fp_adv_stripe_get_intent($id){$secret=fp_adv_stripe_secret();if(!$secret||!$id)return new WP_Error('stripe','Stripe is not configured.');$r=wp_remote_get('https://api.stripe.com/v1/payment_intents/'.rawurlencode($id),['timeout'=>20,'headers'=>['Authorization'=>'Bearer '.$secret]]);if(is_wp_error($r))return $r;$x=json_decode(wp_remote_retrieve_body($r),true);if(wp_remote_retrieve_response_code($r)!==200)return new WP_Error('stripe',$x['error']['message']??'Stripe lookup failed.');return $x;}
function fp_adv_verify_payment($event,$intent_id){$price=fp_adv_event_price($event);if($price<=0)return true;if(!fp_sched_feature('stripe'))return new WP_Error('upgrade_required','Paid scheduling requires the Stripe feature.',['status'=>403]);$x=fp_adv_stripe_get_intent($intent_id);if(is_wp_error($x))return $x;$s=fp_sched_event_settings($event);$currency=strtolower($s['currency']??'usd');$expected=(int)round($price*100);if(($x['status']??'')!=='succeeded'||(int)($x['amount_received']??0)<$expected||strtolower($x['currency']??'')!==$currency)return new WP_Error('payment_required','Payment is not complete.',['status'=>402]);return $x;}
add_action('rest_api_init',function(){register_rest_route('formpilot/v1','/scheduler/payment-intent',['methods'=>'POST','permission_callback'=>'__return_true','callback'=>function(WP_REST_Request $r){$g=fp_adv_public_guard('payment-intent',15);if(is_wp_error($g))return $g;$e=fp_sched_event(absint($r['event_id']));if(!$e||!$e->active)return new WP_Error('not_found','Event not found.',['status'=>404]);$price=fp_adv_event_price($e);if($price<=0)return new WP_Error('not_paid','This event does not require payment.',['status'=>400]);$secret=fp_adv_stripe_secret();if(!$secret)return new WP_Error('stripe_config','Stripe is not configured.',['status'=>503]);$s=fp_sched_event_settings($e);$currency=strtolower($s['currency']??'usd');$body=['amount'=>(int)round($price*100),'currency'=>$currency,'automatic_payment_methods[enabled]'=>'true','description'=>'FormPilot: '.$e->title,'metadata[event_id]'=>(int)$e->id,'metadata[source]'=>'formpilot_scheduler'];$x=wp_remote_post('https://api.stripe.com/v1/payment_intents',['timeout'=>20,'headers'=>['Authorization'=>'Bearer '.$secret,'Content-Type'=>'application/x-www-form-urlencoded'],'body'=>http_build_query($body)]);if(is_wp_error($x))return $x;$data=json_decode(wp_remote_retrieve_body($x),true);if(wp_remote_retrieve_response_code($x)!==200)return new WP_Error('stripe',$data['error']['message']??'Stripe error.',['status'=>502]);return ['client_secret'=>$data['client_secret'],'payment_intent_id'=>$data['id'],'amount'=>$price,'currency'=>strtoupper($currency)];}]);});

/* Integrations and conferencing. */
function fp_adv_integration($user,$provider){global $wpdb;$a=fp_adv_tables();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$a['integrations']} WHERE user_id=%d AND provider=%s AND active=1",$user,$provider));if(!$r)return null;$r->config=json_decode($r->config,true);return $r;}
function fp_adv_zoom_token($cfg){$account=$cfg['account_id']??'';$id=$cfg['client_id']??'';$secret=$cfg['client_secret']??'';if(!$account||!$id||!$secret)return new WP_Error('zoom_config','Zoom credentials are incomplete.');$r=wp_remote_post('https://zoom.us/oauth/token?grant_type=account_credentials&account_id='.rawurlencode($account),['timeout'=>20,'headers'=>['Authorization'=>'Basic '.base64_encode($id.':'.$secret)]]);if(is_wp_error($r))return $r;$x=json_decode(wp_remote_retrieve_body($r),true);return !empty($x['access_token'])?$x['access_token']:new WP_Error('zoom_auth',$x['reason']??'Zoom authorization failed.');}
function fp_adv_create_conference($booking_id){global $wpdb;$t=fp_sched_tables();$b=$wpdb->get_row($wpdb->prepare("SELECT b.*,e.title,e.location_type,e.location_value,e.user_id,e.timezone FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d",$booking_id));if(!$b)return; $loc='';
    if($b->location_type==='meet' && function_exists('ssb_create_google_calendar_event') && function_exists('ssb_google_is_connected') && ssb_google_is_connected()){$parts=preg_split('/\s+/',trim($b->invitee_name),2);$payload=['first_name'=>$parts[0]??$b->invitee_name,'last_name'=>$parts[1]??'','email'=>$b->invitee_email,'phone'=>$b->invitee_phone,'timezone'=>$b->timezone,'timezone_display'=>$b->timezone,'canonical_start_iso'=>gmdate('c',strtotime($b->start_at.' UTC')),'canonical_end_iso'=>gmdate('c',strtotime($b->end_at.' UTC'))];$g=ssb_create_google_calendar_event($payload,['event_label'=>$b->title]);if(!is_wp_error($g)){$loc=$g['meet_link']??$g['html_link']??'';$wpdb->update($t['bookings'],['google_event_id'=>$g['event_id']??'','location'=>$loc,'updated_at'=>fp_sched_now()],['id'=>$booking_id]);}}
    elseif($b->location_type==='zoom'){$i=fp_adv_integration($b->user_id,'zoom');if($i){$token=fp_adv_zoom_token($i->config);if(!is_wp_error($token)){$host=$i->config['host_user']??'me';$body=['topic'=>$b->title,'type'=>2,'start_time'=>gmdate('Y-m-d\TH:i:s\Z',strtotime($b->start_at.' UTC')),'duration'=>max(1,(int)round((strtotime($b->end_at)-strtotime($b->start_at))/60)),'timezone'=>'UTC','settings'=>['waiting_room'=>true,'join_before_host'=>false]];$r=wp_remote_post('https://api.zoom.us/v2/users/'.rawurlencode($host).'/meetings',['timeout'=>20,'headers'=>['Authorization'=>'Bearer '.$token,'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);$x=json_decode(wp_remote_retrieve_body($r),true);if(!is_wp_error($r)&&wp_remote_retrieve_response_code($r)===201){$loc=$x['join_url']??'';$wpdb->update($t['bookings'],['external_id'=>'zoom:'.($x['id']??''),'location'=>$loc,'updated_at'=>fp_sched_now()],['id'=>$booking_id]);}}}}
    elseif($b->location_type==='teams'){$i=fp_adv_integration($b->user_id,'teams');if($i && !empty($i->config['access_token'])){$endpoint=!empty($i->config['user_id'])?'https://graph.microsoft.com/v1.0/users/'.rawurlencode($i->config['user_id']).'/onlineMeetings':'https://graph.microsoft.com/v1.0/me/onlineMeetings';$body=['startDateTime'=>gmdate('c',strtotime($b->start_at.' UTC')),'endDateTime'=>gmdate('c',strtotime($b->end_at.' UTC')),'subject'=>$b->title];$r=wp_remote_post($endpoint,['timeout'=>20,'headers'=>['Authorization'=>'Bearer '.$i->config['access_token'],'Content-Type'=>'application/json'],'body'=>wp_json_encode($body)]);$x=json_decode(wp_remote_retrieve_body($r),true);if(!is_wp_error($r)&&wp_remote_retrieve_response_code($r)>=200&&wp_remote_retrieve_response_code($r)<300){$loc=$x['joinWebUrl']??'';$wpdb->update($t['bookings'],['external_id'=>'teams:'.($x['id']??''),'location'=>$loc,'updated_at'=>fp_sched_now()],['id'=>$booking_id]);}}}
    if($loc)fp_sched_log('conference.created',$booking_id,['location'=>$loc],$b->user_id);
}
add_action('fp_sched_booking_created','fp_adv_create_conference',5);

/* CRM contact sync. */
function fp_adv_crm_sync($booking_id){ if(!fp_sched_feature('crm_integrations'))return; global $wpdb;$t=fp_sched_tables();$b=$wpdb->get_row($wpdb->prepare("SELECT b.*,e.user_id,e.title FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d",$booking_id));if(!$b)return;
    $hub=fp_adv_integration($b->user_id,'hubspot'); if($hub && !empty($hub->config['token'])){$props=['email'=>$b->invitee_email,'firstname'=>$b->invitee_name,'phone'=>$b->invitee_phone];$search=wp_remote_post('https://api.hubapi.com/crm/v3/objects/contacts/search',['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$hub->config['token'],'Content-Type'=>'application/json'],'body'=>wp_json_encode(['filterGroups'=>[['filters'=>[['propertyName'=>'email','operator'=>'EQ','value'=>$b->invitee_email]]]],'properties'=>['email'],'limit'=>1])]);$sx=json_decode(wp_remote_retrieve_body($search),true);$hid=$sx['results'][0]['id']??'';$url=$hid?'https://api.hubapi.com/crm/v3/objects/contacts/'.$hid:'https://api.hubapi.com/crm/v3/objects/contacts';$args=['timeout'=>15,'method'=>$hid?'PATCH':'POST','headers'=>['Authorization'=>'Bearer '.$hub->config['token'],'Content-Type'=>'application/json'],'body'=>wp_json_encode(['properties'=>$props])];wp_remote_request($url,$args);}
    $sf=fp_adv_integration($b->user_id,'salesforce'); if($sf&&!empty($sf->config['instance_url'])&&!empty($sf->config['access_token'])){$base=rtrim($sf->config['instance_url'],'/');$auth=['Authorization'=>'Bearer '.$sf->config['access_token'],'Content-Type'=>'application/json'];$q="SELECT Id FROM Contact WHERE Email='".str_replace("'","\\'",$b->invitee_email)."' LIMIT 1";$r=wp_remote_get($base.'/services/data/v61.0/query?q='.rawurlencode($q),['timeout'=>15,'headers'=>$auth]);$x=json_decode(wp_remote_retrieve_body($r),true);$id=$x['records'][0]['Id']??'';$name=preg_split('/\s+/',trim($b->invitee_name),2);$payload=['FirstName'=>$name[0]??'','LastName'=>$name[1]??($name[0]??'Contact'),'Email'=>$b->invitee_email,'Phone'=>$b->invitee_phone];wp_remote_request($id?$base.'/services/data/v61.0/sobjects/Contact/'.$id:$base.'/services/data/v61.0/sobjects/Contact',['timeout'=>15,'method'=>$id?'PATCH':'POST','headers'=>$auth,'body'=>wp_json_encode($payload)]);}
}
add_action('fp_sched_booking_created','fp_adv_crm_sync',20);

/* Invoices. */
function fp_adv_create_invoice($booking_id,$payment_reference=''){if(!fp_sched_feature('invoices'))return 0;global $wpdb;$t=fp_sched_tables();$a=fp_adv_tables();$b=$wpdb->get_row($wpdb->prepare("SELECT b.*,e.user_id,e.settings FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d",$booking_id));if(!$b)return 0;$s=json_decode($b->settings,true);$amount=(float)($s['price']??0);if($amount<=0)return 0;$currency=strtoupper($s['currency']??'USD');$num='FP-'.gmdate('Ymd').'-'.str_pad((string)$booking_id,6,'0',STR_PAD_LEFT);$token=bin2hex(random_bytes(20));$wpdb->insert($a['invoices'],['user_id'=>$b->user_id,'booking_id'=>$booking_id,'invoice_number'=>$num,'public_token'=>$token,'currency'=>$currency,'subtotal'=>$amount,'tax'=>0,'total'=>$amount,'status'=>$payment_reference?'paid':'open','payment_reference'=>$payment_reference,'issued_at'=>fp_sched_now(),'paid_at'=>$payment_reference?fp_sched_now():null]);$id=(int)$wpdb->insert_id;if($id)$wpdb->update($t['bookings'],['invoice_id'=>$id],['id'=>$booking_id]);return $id;}

/* Booking lifecycle: manage/cancel/reschedule and recurring series. */
function fp_adv_booking_by_token($token){global $wpdb;$t=fp_sched_tables();return $wpdb->get_row($wpdb->prepare("SELECT b.*,e.title,e.slug,e.duration,e.timezone,e.user_id,e.location_type FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.manage_token=%s",$token));}
function fp_adv_cancel_booking($b){global $wpdb;$t=fp_sched_tables();if($b->status==='cancelled')return true;$wpdb->update($t['bookings'],['status'=>'cancelled','cancelled_at'=>fp_sched_now(),'updated_at'=>fp_sched_now()],['id'=>$b->id]);if(!empty($b->google_event_id)&&function_exists('ssb_delete_google_calendar_event'))ssb_delete_google_calendar_event($b->google_event_id);fp_sched_log('booking.cancelled',$b->id,[],$b->user_id);fp_adv_webhook_enqueue('booking.cancelled',['id'=>(int)$b->id,'event_id'=>(int)$b->event_id]);fp_adv_enqueue_workflows($b->id,'booking.cancelled');return true;}
function fp_adv_reschedule_booking($b,$start_local){global $wpdb;$t=fp_sched_tables();$e=fp_sched_event($b->event_id);if(!$e)return new WP_Error('event','Event missing.');$tz=new DateTimeZone($e->timezone?:'UTC');try{$s=new DateTime($start_local,$tz);}catch(Exception $x){return new WP_Error('time','Invalid time.');}$end=(clone $s)->modify('+'.(int)$e->duration.' minutes');$utc=(clone $s)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$utcEnd=(clone $end)->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s');$hosts=fp_sched_hosts_for_slot($e,$utc,$utcEnd);if(!$hosts)return new WP_Error('slot','That time is unavailable.');$wpdb->update($t['bookings'],['host_user_id'=>(int)$hosts[0],'start_at'=>$utc,'end_at'=>$utcEnd,'updated_at'=>fp_sched_now(),'google_event_id'=>''],['id'=>$b->id]);$a=fp_adv_tables();$wpdb->delete($a['booking_hosts'],['booking_id'=>$b->id]);fp_adv_store_booking_hosts($b->id,$hosts);if(!empty($b->google_event_id)&&function_exists('ssb_delete_google_calendar_event'))ssb_delete_google_calendar_event($b->google_event_id);fp_adv_create_conference($b->id);fp_sched_log('booking.rescheduled',$b->id,['start_at'=>$utc],$b->user_id);fp_adv_webhook_enqueue('booking.rescheduled',['id'=>(int)$b->id,'start_at'=>$utc]);fp_adv_enqueue_workflows($b->id,'booking.rescheduled');return true;}
add_action('rest_api_init',function(){
    register_rest_route('formpilot/v1','/manage/(?P<token>[A-Fa-f0-9]{32,64})',['methods'=>'GET','permission_callback'=>'__return_true','callback'=>function(WP_REST_Request $r){$g=fp_adv_public_guard('manage-get',40);if(is_wp_error($g))return $g;$b=fp_adv_booking_by_token($r['token']);if(!$b)return new WP_Error('not_found','Booking not found.',['status'=>404]);return ['id'=>(int)$b->id,'event_id'=>(int)$b->event_id,'title'=>$b->title,'start_at'=>$b->start_at,'end_at'=>$b->end_at,'timezone'=>$b->timezone,'status'=>$b->status,'location'=>$b->location];}]);
    register_rest_route('formpilot/v1','/manage/(?P<token>[A-Fa-f0-9]{32,64})/cancel',['methods'=>'POST','permission_callback'=>'__return_true','callback'=>function(WP_REST_Request $r){$g=fp_adv_public_guard('manage-cancel',10);if(is_wp_error($g))return $g;$b=fp_adv_booking_by_token($r['token']);if(!$b)return new WP_Error('not_found','Booking not found.',['status'=>404]);fp_adv_cancel_booking($b);return ['success'=>true];}]);
    register_rest_route('formpilot/v1','/manage/(?P<token>[A-Fa-f0-9]{32,64})/reschedule',['methods'=>'POST','permission_callback'=>'__return_true','callback'=>function(WP_REST_Request $r){$g=fp_adv_public_guard('manage-reschedule',12);if(is_wp_error($g))return $g;$b=fp_adv_booking_by_token($r['token']);if(!$b)return new WP_Error('not_found','Booking not found.',['status'=>404]);$x=fp_adv_reschedule_booking($b,sanitize_text_field($r['start']));if(is_wp_error($x))return $x;return ['success'=>true];}]);
    register_rest_route('formpilot/v1','/booking/recurring',['methods'=>'POST','permission_callback'=>'__return_true','callback'=>'fp_adv_recurring_booking_rest']);
});
function fp_adv_recurring_booking_rest(WP_REST_Request $r){$g=fp_adv_public_guard('booking-recurring',8);if(is_wp_error($g))return $g;if(!fp_sched_feature('workflows'))return new WP_Error('upgrade_required','Recurring booking requires FormPilot Pro.',['status'=>403]);$e=fp_sched_event(absint($r['event_id']));if(!$e||!$e->active)return new WP_Error('event','Event not found.',['status'=>404]);if(function_exists('fp_adv_event_price')&&fp_adv_event_price($e)>0)return new WP_Error('recurring_paid','Recurring series currently require a zero-price event.',['status'=>400]);$count=min(12,max(2,absint($r['count']??2)));$frequency=sanitize_key($r['frequency']??'weekly');if(!in_array($frequency,['daily','weekly','monthly'],true))$frequency='weekly';$name=sanitize_text_field($r['name']);$email=sanitize_email($r['email']);$phone=sanitize_text_field($r['phone']);$start=sanitize_text_field($r['start']);$series=bin2hex(random_bytes(12));$created=[];for($i=0;$i<$count;$i++){try{$dt=new DateTime($start,new DateTimeZone($e->timezone?:'UTC'));if($i)$dt->modify('+'.$i.' '.$frequency);$id=fp_sched_booking_create($e,$name,$email,$phone,$dt->format('Y-m-d H:i:s'),['series_key'=>$series]);if(is_wp_error($id)){foreach($created as $cid){global $wpdb;$t=fp_sched_tables();$wpdb->update($t['bookings'],['status'=>'cancelled'],['id'=>$cid]);}return $id;}global $wpdb;$t=fp_sched_tables();$wpdb->update($t['bookings'],['series_key'=>$series],['id'=>$id]);$created[]=$id;}catch(Exception $x){return new WP_Error('recurrence',$x->getMessage());}}return ['success'=>true,'series_key'=>$series,'booking_ids'=>$created];}

/* Public meeting poll. */
function fp_adv_poll_public($id){global $wpdb;$t=fp_sched_tables();$p=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['polls']} WHERE id=%d",$id));if(!$p)return '<p>Poll not found.</p>';$opts=$wpdb->get_results($wpdb->prepare("SELECT o.*,SUM(CASE WHEN v.vote=1 THEN 1 ELSE 0 END) votes FROM {$t['poll_options']} o LEFT JOIN {$t['poll_votes']} v ON v.option_id=o.id WHERE o.poll_id=%d GROUP BY o.id ORDER BY o.start_at",$id));ob_start();?><div class="formpilot-poll" style="max-width:760px;margin:30px auto;padding:24px;border:1px solid #e5e7eb;border-radius:16px"><h2><?php echo esc_html($p->title);?></h2><p><?php echo esc_html($p->description);?></p><form id="fp-poll-<?php echo (int)$p->id;?>"><p><input name="name" placeholder="Your name" required> <input type="email" name="email" placeholder="Email" required></p><?php foreach($opts as $o):?><label style="display:block;padding:12px;border:1px solid #ddd;margin:8px 0;border-radius:10px"><input type="checkbox" name="option" value="<?php echo (int)$o->id;?>"> <?php echo esc_html(get_date_from_gmt($o->start_at,'D, M j Y g:i a'));?> <small>(<?php echo (int)$o->votes;?> votes)</small></label><?php endforeach;?><button class="button button-primary">Submit availability</button> <span class="fp-poll-msg"></span></form></div><script>(function(){var f=document.getElementById('fp-poll-<?php echo (int)$p->id;?>');f.addEventListener('submit',async function(ev){ev.preventDefault();var boxes=f.querySelectorAll('input[name=option]:checked');for(var i=0;i<boxes.length;i++){await fetch('<?php echo esc_url(rest_url('formpilot/v1/poll/'.$p->id.'/vote'));?>',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({option_id:boxes[i].value,name:f.name.value,email:f.email.value,vote:true})});}f.querySelector('.fp-poll-msg').textContent=' Saved.';});})();</script><?php return ob_get_clean();}
add_action('init',function(){if(!is_admin()&&isset($_GET['formpilot_poll'])){$id=absint($_GET['formpilot_poll']);add_filter('the_content',function($c)use($id){return fp_adv_poll_public($id);},99);}if(!is_admin()&&isset($_GET['formpilot_manage'])){$token=preg_replace('/[^A-Fa-f0-9]/','',wp_unslash($_GET['formpilot_manage']));add_filter('the_content',function($c)use($token){return fp_adv_manage_page($token);},99);}});
function fp_adv_manage_page($token){$b=fp_adv_booking_by_token($token);if(!$b)return '<p>Booking not found.</p>';ob_start();?><div style="max-width:760px;margin:30px auto;padding:24px;border:1px solid #e5e7eb;border-radius:16px"><h2>Manage booking</h2><p><strong><?php echo esc_html($b->title);?></strong></p><p><?php echo esc_html(get_date_from_gmt($b->start_at,'F j, Y g:i a'));?> · <?php echo esc_html($b->timezone);?></p><p>Status: <strong id="fp-manage-status"><?php echo esc_html($b->status);?></strong></p><?php if($b->status==='scheduled'):?><p><label>New date/time <input type="datetime-local" id="fp-new-start"></label> <button type="button" class="button" id="fp-reschedule">Reschedule</button></p><button type="button" class="button" id="fp-cancel">Cancel booking</button><?php endif;?></div><script>(function(){var token='<?php echo esc_js($token);?>',base='<?php echo esc_url(rest_url('formpilot/v1/manage/'));?>'+token;var c=document.getElementById('fp-cancel');if(c)c.onclick=function(){if(!confirm('Cancel this booking?'))return;fetch(base+'/cancel',{method:'POST'}).then(r=>r.json()).then(x=>{if(x.success){document.getElementById('fp-manage-status').textContent='cancelled';location.reload();}else alert(x.message||'Could not cancel');});};var rs=document.getElementById('fp-reschedule');if(rs)rs.onclick=function(){var v=document.getElementById('fp-new-start').value;if(!v)return;fetch(base+'/reschedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start:v.replace('T',' ')})}).then(r=>r.json()).then(x=>{if(x.success)location.reload();else alert(x.message||'Could not reschedule');});};})();</script><?php return ob_get_clean();}

/* API keys and authenticated business API. */
function fp_adv_api_auth(WP_REST_Request $r){$h=$r->get_header('authorization');if(!$h||stripos($h,'Bearer ')!==0)return new WP_Error('unauthorized','API key required.',['status'=>401]);$raw=trim(substr($h,7));if(strpos($raw,'fp_')!==0)return new WP_Error('unauthorized','Invalid API key.',['status'=>401]);global $wpdb;$a=fp_adv_tables();$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$a['api_keys']} WHERE key_hash=%s AND active=1",hash('sha256',$raw)));if(!$row)return new WP_Error('unauthorized','Invalid API key.',['status'=>401]);$wpdb->update($a['api_keys'],['last_used_at'=>fp_sched_now()],['id'=>$row->id]);$r->set_param('_fp_user_id',(int)$row->user_id);return true;}
add_action('rest_api_init',function(){register_rest_route('formpilot/v1','/business/bookings',['methods'=>'GET','permission_callback'=>'fp_adv_api_auth','callback'=>function(WP_REST_Request $r){global $wpdb;$t=fp_sched_tables();$u=absint($r['_fp_user_id']);return $wpdb->get_results($wpdb->prepare("SELECT b.id,b.event_id,b.invitee_name,b.invitee_email,b.start_at,b.end_at,b.status,b.payment_status,b.payment_amount,b.location FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE e.user_id=%d ORDER BY b.start_at DESC LIMIT 500",$u),ARRAY_A);}]);register_rest_route('formpilot/v1','/business/contacts',['methods'=>'GET','permission_callback'=>'fp_adv_api_auth','callback'=>function(WP_REST_Request $r){global $wpdb;$t=fp_sched_tables();return $wpdb->get_results($wpdb->prepare("SELECT id,name,email,phone,company,last_booking_at FROM {$t['contacts']} WHERE user_id=%d ORDER BY updated_at DESC LIMIT 500",absint($r['_fp_user_id'])),ARRAY_A);}]);register_rest_route('formpilot/v1','/business/analytics',['methods'=>'GET','permission_callback'=>'fp_adv_api_auth','callback'=>function(WP_REST_Request $r){return fp_adv_analytics(absint($r['_fp_user_id']),absint($r['days']?:30));}]);});
function fp_adv_analytics($user,$days=30){global $wpdb;$t=fp_sched_tables();$days=min(365,max(1,$days));$since=gmdate('Y-m-d H:i:s',time()-$days*DAY_IN_SECONDS);$summary=$wpdb->get_row($wpdb->prepare("SELECT COUNT(*) bookings,SUM(CASE WHEN b.status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN b.payment_status='paid' THEN b.payment_amount ELSE 0 END) revenue,COUNT(DISTINCT b.invitee_email) unique_invitees FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE e.user_id=%d AND b.created_at>=%s",$user,$since),ARRAY_A);$daily=$wpdb->get_results($wpdb->prepare("SELECT DATE(b.created_at) day,COUNT(*) bookings,SUM(CASE WHEN b.status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN b.payment_status='paid' THEN b.payment_amount ELSE 0 END) revenue FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE e.user_id=%d AND b.created_at>=%s GROUP BY DATE(b.created_at) ORDER BY day",$user,$since),ARRAY_A);$events=$wpdb->get_results($wpdb->prepare("SELECT e.id,e.title,COUNT(b.id) bookings FROM {$t['events']} e LEFT JOIN {$t['bookings']} b ON b.event_id=e.id AND b.created_at>=%s WHERE e.user_id=%d GROUP BY e.id ORDER BY bookings DESC",$since,$user),ARRAY_A);return ['days'=>$days,'summary'=>$summary,'daily'=>$daily,'events'=>$events];}

