function fp_adv_integration_record($user,$provider){global $wpdb;$a=fp_adv_tables();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$a['integrations']} WHERE user_id=%d AND provider=%s LIMIT 1",$user,$provider));if(!$r)return null;$r->config=json_decode($r->config,true);return $r;}
function fp_adv_masked_integration($provider){
    $x=fp_adv_integration_record(get_current_user_id(),$provider); return $x?$x->config:[];
}

function fp_adv_save_integration($provider,$fields){
    global $wpdb; $a=fp_adv_tables(); $uid=get_current_user_id(); $existing=fp_adv_integration($uid,$provider); $old=$existing?$existing->config:[]; $cfg=[];
    foreach($fields as $key=>$def){
        $raw=isset($_POST['fp_'.$provider.'_'.$key])?wp_unslash($_POST['fp_'.$provider.'_'.$key]):'';
        if(!empty($def['secret']) && $raw==='') { $cfg[$key]=$old[$key]??''; }
        else if($def['type']==='url') { $cfg[$key]=esc_url_raw($raw); }
        else { $cfg[$key]=sanitize_text_field($raw); }
    }
    $data=['user_id'=>$uid,'provider'=>$provider,'label'=>sanitize_text_field($_POST['fp_'.$provider.'_label']??''),'config'=>wp_json_encode($cfg),'active'=>isset($_POST['fp_'.$provider.'_active'])?1:0,'updated_at'=>fp_sched_now()];
    if($existing) $wpdb->update($a['integrations'],$data,['id'=>$existing->id]); else {$data['created_at']=fp_sched_now();$wpdb->insert($a['integrations'],$data);}
    return $cfg;
}

function fp_adv_test_integration($provider,$cfg){
    switch($provider){
        case 'google':
            if(!function_exists('ssb_google_get_access_token'))return new WP_Error('google_test','Google Calendar support is unavailable.');
            $token=ssb_google_get_access_token(); if(!$token)return new WP_Error('google_test','No valid Google access token. Click Connect to Google Calendar first.');
            $cal=get_option('ssb_google_calendar_id','primary');
            $r=wp_remote_get('https://www.googleapis.com/calendar/v3/calendars/'.rawurlencode($cal),['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$token]]);
            $x=json_decode(wp_remote_retrieve_body($r),true); if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('google_test',$x['error']['message']??'Google Calendar connection test failed.');
            return ['message'=>'Connected to Google Calendar'.(!empty($x['summary'])?' — '.$x['summary']:'').'.'];
        case 'stripe':
            $secret=fp_adv_stripe_secret(); if(!$secret)return new WP_Error('stripe_test','Stripe secret key is missing. Save it before testing.');
            $r=wp_remote_get('https://api.stripe.com/v1/account',['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$secret]]);$x=json_decode(wp_remote_retrieve_body($r),true);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('stripe_test',$x['error']['message']??'Stripe connection test failed.');return ['message'=>'Connected to Stripe'.(!empty($x['business_profile']['name'])?' — '.$x['business_profile']['name']:'').' ('.(get_option('ssb_stripe_test_mode','1')==='1'?'test mode':'live mode').').'];
        case 'zoom':
            $token=fp_adv_zoom_token($cfg); if(is_wp_error($token))return $token;
            $r=wp_remote_get('https://api.zoom.us/v2/users/'.rawurlencode($cfg['host_user']??'me'),['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$token]]);
            $x=json_decode(wp_remote_retrieve_body($r),true); if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('zoom_test',$x['message']??'Zoom connection test failed.'); return ['message'=>'Connected to Zoom as '.($x['email']??$x['first_name']??'the configured host').'.'];
        case 'teams':
            $tenant=$cfg['tenant_id']??'';$cid=$cfg['client_id']??'';$sec=$cfg['client_secret']??''; if(!$tenant||!$cid||!$sec)return new WP_Error('teams_config','Microsoft Teams credentials are incomplete.');
            $r=wp_remote_post('https://login.microsoftonline.com/'.rawurlencode($tenant).'/oauth2/v2.0/token',['timeout'=>15,'body'=>['client_id'=>$cid,'client_secret'=>$sec,'scope'=>'https://graph.microsoft.com/.default','grant_type'=>'client_credentials']]);
            $x=json_decode(wp_remote_retrieve_body($r),true); if(is_wp_error($r)||empty($x['access_token']))return new WP_Error('teams_auth',$x['error_description']??'Microsoft authentication failed.');
            $i=$cfg; $i['access_token']=$x['access_token']; $r=wp_remote_get('https://graph.microsoft.com/v1.0/users/'.rawurlencode($cfg['user_id']??''),['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$x['access_token']]]);$u=json_decode(wp_remote_retrieve_body($r),true);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('teams_test',$u['error']['message']??'Microsoft Graph test failed.');
            global $wpdb;$a=fp_adv_tables();$wpdb->update($a['integrations'],['config'=>wp_json_encode($i),'updated_at'=>fp_sched_now()],['user_id'=>get_current_user_id(),'provider'=>'teams']);return ['message'=>'Connected to Microsoft 365 as '.($u['displayName']??$u['userPrincipalName']??'the configured organizer').'.'];
        case 'hubspot':
            $token=$cfg['token']??''; if(!$token)return new WP_Error('hubspot_config','HubSpot access token is missing.');
            $r=wp_remote_get('https://api.hubapi.com/crm/v3/objects/contacts?limit=1',['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$token]]);$x=json_decode(wp_remote_retrieve_body($r),true);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('hubspot_test',$x['message']??'HubSpot connection test failed.');return ['message'=>'Connected to HubSpot CRM.'];
        case 'salesforce':
            $base=rtrim($cfg['instance_url']??'','/');$token=$cfg['access_token']??'';if(!$base||!$token)return new WP_Error('salesforce_config','Salesforce instance URL and access token are required.');
            $r=wp_remote_get($base.'/services/data/v61.0/limits',['timeout'=>15,'headers'=>['Authorization'=>'Bearer '.$token]]);$x=json_decode(wp_remote_retrieve_body($r),true);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)return new WP_Error('salesforce_test',$x[0]['message']??'Salesforce connection test failed.');return ['message'=>'Connected to Salesforce.'];
    }
    return new WP_Error('unsupported','Unsupported integration.');
}

add_action('wp_ajax_fp_test_integration','fp_adv_ajax_test_integration');
function fp_adv_ajax_test_integration(){
    if(!current_user_can('manage_options')||!check_ajax_referer('fp_integrations_nonce','nonce',false))wp_send_json_error(['message'=>'Security check failed.'],403);
    if(function_exists('ssb_license_can') && !ssb_license_can('integrations'))wp_send_json_error(['message'=>'FormPilot Pro license required.'],403);
    $provider=sanitize_key($_POST['provider']??'');$defs=fp_adv_integration_configs();$supported=array_merge(array_keys($defs),['google','stripe']);if(!in_array($provider,$supported,true))wp_send_json_error(['message'=>'Unknown provider.'],400);
    $cfg=$provider==='google'?['client_id'=>get_option('ssb_google_client_id',''),'client_secret'=>get_option('ssb_google_client_secret','')]:($provider==='stripe'?['secret_key'=>fp_adv_stripe_secret()]:fp_adv_masked_integration($provider));
    if(!$cfg)wp_send_json_error(['message'=>'Save the integration before testing it.'],400);$x=fp_adv_test_integration($provider,$cfg);if(is_wp_error($x))wp_send_json_error(['message'=>$x->get_error_message()],400);wp_send_json_success($x);
}

