function fp_adv_routing_builder_page(){fp_sched_gate('routing');global $wpdb;$t=fp_sched_tables();$u=get_current_user_id();if(isset($_POST['fp_route_builder_save'])&&check_admin_referer('fp_route_builder')){$rid=absint($_POST['routing_id']);$questions=[];foreach((array)($_POST['q_key']??[]) as $i=>$key){$key=sanitize_key($key);if(!$key)continue;$questions[]=['key'=>$key,'label'=>sanitize_text_field($_POST['q_label'][$i]??$key),'type'=>'select','options'=>array_values(array_filter(array_map('trim',explode('|',sanitize_text_field($_POST['q_options'][$i]??'')))) )];}$rules=[];foreach((array)($_POST['r_key']??[]) as $i=>$key){$key=sanitize_key($key);if(!$key)continue;$rules[]=['if'=>$key,'op'=>sanitize_key($_POST['r_op'][$i]??'eq'),'value'=>sanitize_text_field($_POST['r_value'][$i]??''),'event_id'=>absint($_POST['r_event'][$i]??0)];}$wpdb->update($t['routing'],['questions'=>wp_json_encode($questions),'rules'=>wp_json_encode($rules),'default_event_id'=>absint($_POST['default_event_id'])],['id'=>$rid,'user_id'=>$u]);echo '<div class="notice notice-success"><p>Routing logic saved.</p></div>';}$routes=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$t['routing']} WHERE user_id=%d",$u));$events=$wpdb->get_results($wpdb->prepare("SELECT id,title FROM {$t['events']} WHERE user_id=%d AND active=1",$u));fp_sched_header('Routing Builder');echo '<p>Build multiple questions and ordered rules. Operators: equals, not equals, contains, starts with.</p><form method="post">'.wp_nonce_field('fp_route_builder','_wpnonce',true,false).'<input type="hidden" name="fp_route_builder_save" value="1"><p><select name="routing_id">';foreach($routes as $r)echo '<option value="'.(int)$r->id.'">'.esc_html($r->name).'</option>';echo '</select> Default <select name="default_event_id">';foreach($events as $e)echo '<option value="'.(int)$e->id.'">'.esc_html($e->title).'</option>';echo '</select></p><h3>Questions</h3><div id="fp-q"></div><button type="button" class="button" onclick="fpAddQ()">Add question</button><h3>Rules</h3><div id="fp-r"></div><button type="button" class="button" onclick="fpAddR()">Add rule</button><p><button class="button button-primary">Save routing logic</button></p></form><script>function fpAddQ(){document.getElementById("fp-q").insertAdjacentHTML("beforeend",`<p><input name="q_key[]" placeholder="company_size"> <input name="q_label[]" placeholder="Company size"> <input class="regular-text" name="q_options[]" placeholder="1-10|11-50|51+"></p>`)}function fpAddR(){var ev='.wp_json_encode(array_map(function($e){return ['id'=>(int)$e->id,'title'=>$e->title];},$events)).';var options=ev.map(x=>`<option value="${x.id}">${x.title}</option>`).join("");document.getElementById("fp-r").insertAdjacentHTML("beforeend",`<p><input name="r_key[]" placeholder="company_size"> <select name="r_op[]"><option value="eq">equals</option><option value="neq">not equals</option><option value="contains">contains</option><option value="starts">starts with</option></select> <input name="r_value[]" placeholder="51+"> <select name="r_event[]">${options}</select></p>`)}fpAddQ();fpAddR();</script>';fp_sched_footer();}
