function fp_adv_marketplace_catalog(){
    $url=rtrim(SSB_LICENSE_SERVER_URL,'/').'/wp-json/formpilot/v1/templates/catalog';
    $r=wp_remote_get($url,['timeout'=>8,'headers'=>['Accept'=>'application/json','X-FormPilot-Product'=>'formpilot-pro']]);
    if(!is_wp_error($r)&&wp_remote_retrieve_response_code($r)===200){$x=json_decode(wp_remote_retrieve_body($r),true);if(is_array($x['templates']??null)&&$x['templates'])return $x['templates'];}
    return fp_adv_marketplace_local_catalog();
}
function fp_adv_marketplace_get_template($slug){
    $slug=sanitize_title($slug); $url=rtrim(SSB_LICENSE_SERVER_URL,'/').'/wp-json/formpilot/v1/templates/item/'.rawurlencode($slug);
    $r=wp_remote_get($url,['timeout'=>8,'headers'=>['Accept'=>'application/json','X-FormPilot-Product'=>'formpilot-pro']]);
    if(!is_wp_error($r)&&wp_remote_retrieve_response_code($r)===200){$x=json_decode(wp_remote_retrieve_body($r),true);if(!empty($x['template']))return $x['template'];}
    foreach(fp_adv_marketplace_local_catalog() as $q)if($q['slug']===$slug)return $q;
    return null;
}
function fp_adv_import_marketplace_template($q){
    global $wpdb;$t=fp_sched_tables();
