    $wpdb->insert($t['events'],$data);$id=(int)$wpdb->insert_id;
    if($id)foreach((array)($q['availability']??[]) as $av){$st=sanitize_text_field($av['start']??'09:00');$en=sanitize_text_field($av['end']??'17:00');$wpdb->insert($t['availability'],['event_id'=>$id,'weekday'=>absint($av['day']??1),'start_time'=>$st.':00','end_time'=>$en.':00']);}
    return $id;
}
