    echo '<div class="fp-market-hero"><div><div class="fp-eyebrow">FORMPILOT PRO</div><h2>Start with a proven scheduling experience</h2><p>Choose a ready-made event, import it in one click, then customize the hosts, availability, location, price and branding.</p></div><div class="fp-market-status '.($remote_ok?'is-online':'is-local').'">'.($remote_ok?'Marketplace connected':'Built-in catalog available').'</div></div>';
    if(!$remote_ok)echo '<div class="notice notice-info"><p><strong>Marketplace server temporarily unavailable.</strong> FormPilot is using its built-in template catalog so you can keep working. Imported templates are fully editable and do not depend on the marketplace server.</p></div>';
    echo '<div class="fp-market-grid">';foreach($cat as $q){$type=ucwords(str_replace('_',' ',$q['type']??'one_on_one'));echo '<article class="fp-market-card"><div class="fp-market-card-head"><span class="fp-market-tag">'.esc_html($type).'</span><span>'.(int)($q['duration']??30).' min</span></div><h2>'.esc_html($q['title']).'</h2><p>'.esc_html($q['summary']??$q['description']??'').'</p><div class="fp-market-meta"><span>'.esc_html(ucwords(str_replace('_',' ', $q['location_type']??'custom'))).'</span><span>'.((float)($q['settings']['price']??0)>0?esc_html(($q['settings']['currency']??'USD').' '.number_format((float)$q['settings']['price'],2)):'Free').'</span></div><form method="post">'.wp_nonce_field('fp_tpl','_wpnonce',true,false).'<input type="hidden" name="slug" value="'.esc_attr($q['slug']).'"><button class="button button-primary" name="fp_tpl_import" value="1">Use this template</button></form></article>';}
    echo '</div><div class="fp-market-help"><strong>How it works</strong><span>1. Choose a template</span><span>2. Import it</span><span>3. Edit the Event Type</span><span>4. Preview and test a booking</span></div>';fp_sched_footer();
}

/* Rich public scheduling page: branding, remaining seats, Stripe, manage link. */
function fp_adv_event_shortcode($atts){$slug=sanitize_title($atts['slug']??'');if(!$slug&&isset($_GET['formpilot_event']))$slug=sanitize_title(wp_unslash($_GET['formpilot_event']));global $wpdb;$t=fp_sched_tables();$e=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['events']} WHERE slug=%s AND active=1",$slug));if(!$e)return '<p>Event not found.</p>';$brand=get_option('fp_sched_branding',[]);$accent=sanitize_hex_color($brand['accent']??'#111827')?:'#111827';$bg=sanitize_hex_color($brand['background']??'#ffffff')?:'#ffffff';$radius=max(0,min(40,absint($brand['radius']??16)));$price=fp_adv_event_price($e);$currency=strtoupper(fp_sched_event_settings($e)['currency']??'USD');if($price>0)wp_enqueue_script('stripe-js','https://js.stripe.com/v3/',[],null,true);$pk=get_option('ssb_stripe_publishable_key','');ob_start();?><div id="fp-scheduler-<?php echo (int)$e->id;?>" class="formpilot-scheduler" style="max-width:900px;margin:30px auto;padding:28px;border:1px solid #e5e7eb;border-radius:<?php echo (int)$radius;?>px;background:<?php echo esc_attr($bg);?>"><style>#fp-scheduler-<?php echo (int)$e->id;?> .fp-primary{background:<?php echo esc_attr($accent);?>;border-color:<?php echo esc_attr($accent);?>;color:#fff}<?php echo wp_strip_all_tags($brand['custom_css']??'');?></style><?php if(!empty($brand['logo'])):?><img src="<?php echo esc_url($brand['logo']);?>" alt="" style="max-height:48px;margin-bottom:14px"><?php endif;?><h2><?php echo esc_html($e->title);?></h2><p><?php echo esc_html($e->description);?></p><p><strong><?php echo (int)$e->duration;?> min</strong> · <?php echo esc_html($e->timezone);?><?php if($price>0):?> · <strong><?php echo esc_html($currency).' '.number_format($price,2);?></strong><?php endif;?></p><p><label>Date <input type="date" class="fp-date" value="<?php echo esc_attr(wp_date('Y-m-d',strtotime('+1 day')));?>"></label> <button type="button" class="button fp-show">Show times</button></p><div class="fp-slots" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;margin:18px 0"></div><form class="fp-book" style="display:none"><input type="hidden" name="single_use_token" value="<?php echo isset($_GET['formpilot_link'])?esc_attr(sanitize_text_field(wp_unslash($_GET['formpilot_link']))):'';?>"><input type="hidden" name="start"><p><input name="name" placeholder="Full name" required></p><p><input name="email" type="email" placeholder="Email" required></p><p><input name="phone" placeholder="Phone"></p><?php if($price>0):?><div class="fp-card" style="padding:12px;border:1px solid #ddd;border-radius:8px;margin:12px 0"></div><?php endif;?><button class="button fp-primary">Book now</button> <span class="fp-msg"></span></form></div><script>(function(){var root=document.getElementById('fp-scheduler-<?php echo (int)$e->id;?>'),eid=<?php echo (int)$e->id;?>,price=<?php echo wp_json_encode($price);?>,stripe=null,card=null,paymentIntent='';<?php if($price>0 && $pk):?>if(window.Stripe){stripe=Stripe(<?php echo wp_json_encode($pk);?>);card=stripe.elements().create('card');card.mount(root.querySelector('.fp-card'));}<?php endif;?>async function load(){var d=root.querySelector('.fp-date').value;var r=await fetch('<?php echo esc_url(rest_url('formpilot/v1/availability/'));?>'+eid+'?date='+encodeURIComponent(d));var x=await r.json(),box=root.querySelector('.fp-slots');box.innerHTML='';(x.slots||[]).forEach(function(s){var b=document.createElement('button');b.type='button';b.className='button';b.textContent=s.start.slice(11,16)+(s.remaining>1?' · '+s.remaining+' seats':'');b.onclick=function(){root.querySelector('.fp-book').style.display='block';root.querySelector('[name=start]').value=s.start;};box.appendChild(b)});if(!(x.slots||[]).length)box.textContent='No available times.';}root.querySelector('.fp-show').onclick=load;root.querySelector('.fp-book').addEventListener('submit',async function(ev){ev.preventDefault();var f=ev.target,msg=f.querySelector('.fp-msg');msg.textContent=' Processing…';if(price>0){if(!stripe||!card){msg.textContent=' Payment is not configured.';return;}var pi=await fetch('<?php echo esc_url(rest_url('formpilot/v1/scheduler/payment-intent'));?>',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_id:eid})}).then(r=>r.json());if(!pi.client_secret){msg.textContent=' '+(pi.message||'Could not start payment.');return;}var conf=await stripe.confirmCardPayment(pi.client_secret,{payment_method:{card:card,billing_details:{name:f.name.value,email:f.email.value}}});if(conf.error){msg.textContent=' '+conf.error.message;return;}paymentIntent=conf.paymentIntent.id;}var body={event_id:eid,name:f.name.value,email:f.email.value,phone:f.phone.value,start:f.start.value,single_use_token:f.single_use_token.value,payment_intent_id:paymentIntent,answers:{}};var r=await fetch('<?php echo esc_url(rest_url('formpilot/v1/booking'));?>',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':'fp-'+eid+'-'+Date.now()},body:JSON.stringify(body)});var x=await r.json();if(x.success){msg.innerHTML=' Confirmed. '+(x.manage_url?'<a href="'+x.manage_url+'">Manage booking</a>':'');f.reset();root.querySelector('.fp-slots').innerHTML='';}else msg.textContent=' '+(x.message||'Could not book.');});load();})();</script><?php return ob_get_clean();}
add_shortcode('formpilot_event','fp_adv_event_shortcode');

/* Intercept routing resolution to support richer rules. */
add_filter('rest_pre_dispatch',function($result,$server,$request){if($request->get_route()!=='/formpilot/v1/routing/resolve')return $result;global $wpdb;$t=fp_sched_tables();$slug=sanitize_text_field($request['slug']);$x=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['routing']} WHERE slug=%s AND active=1",$slug));if(!$x)return new WP_Error('not_found','Routing form not found',['status'=>404]);$answers=(array)$request['answers'];$target=(int)$x->default_event_id;foreach((array)json_decode($x->rules,true) as $rule){$k=sanitize_key($rule['if']??'');$left=(string)($answers[$k]??'');$right=(string)($rule['value']??$rule['equals']??'');$op=$rule['op']??'eq';$match=$op==='neq'?$left!==$right:($op==='contains'?stripos($left,$right)!==false:($op==='starts'?stripos($left,$right)===0:$left===$right));if($match){$target=absint($rule['event_id']??$target);break;}}$e=fp_sched_event($target);return $e?new WP_REST_Response(['event_id'=>(int)$e->id,'slug'=>$e->slug,'title'=>$e->title],200):new WP_Error('no_event','No event matched',['status'=>404]);},10,3);

/* Public invoice renderer. */
add_action('init',function(){if(is_admin()||empty($_GET['formpilot_invoice']))return;$token=preg_replace('/[^A-Za-z0-9]/','',wp_unslash($_GET['formpilot_invoice']));add_filter('the_content',function($c)use($token){global $wpdb;$a=fp_adv_tables();$t=fp_sched_tables();$i=$wpdb->get_row($wpdb->prepare("SELECT i.*,b.invitee_name,b.invitee_email,e.title FROM {$a['invoices']} i JOIN {$t['bookings']} b ON b.id=i.booking_id JOIN {$t['events']} e ON e.id=b.event_id WHERE i.public_token=%s",$token));if(!$i)return '<p>Invoice not found.</p>';return '<div style="max-width:760px;margin:30px auto;padding:32px;border:1px solid #ddd;background:#fff"><style>@media print{body{background:#fff!important}.fp-invoice-print{display:none!important}}</style><h1>Invoice '.esc_html($i->invoice_number).'</h1><p>'.esc_html($i->invitee_name).' · '.esc_html($i->invitee_email).'</p><table style="width:100%;border-collapse:collapse"><tr><td style="padding:12px 0">'.esc_html($i->title).'</td><td style="text-align:right">'.esc_html($i->currency).' '.number_format((float)$i->subtotal,2).'</td></tr><tr><td><strong>Total</strong></td><td style="text-align:right"><strong>'.esc_html($i->currency).' '.number_format((float)$i->total,2).'</strong></td></tr></table><p>Status: <strong>'.esc_html(strtoupper($i->status)).'</strong></p><p class="fp-invoice-print"><button onclick="window.print()">Print / Save as PDF</button></p><p>Issued '.esc_html($i->issued_at).'</p></div>';},99);});




/* FormPilot 10.4 provider-specific setup pages and product demos. */
function fp_adv_integration_setup_data($provider){
    $guides=function_exists('fp_help_integration_guides')?fp_help_integration_guides():[];
    return $guides[$provider]??[];
}

function fp_adv_integration_status_card($connected,$name,$details=''){
    echo '<div class="fp-int-status-card '.($connected?'is-connected':'is-disconnected').'">';
    echo '<div class="fp-int-status-title"><span class="fp-int-status-dot"></span><strong>'.esc_html($connected?'Connected':'Not Connected').'</strong></div>';
    echo '<p>'.($details!==''?wp_kses_post($details):esc_html($connected?'Connection is active and ready to use.':'Complete the setup below to enable this integration.')).'</p>';
    echo '</div>';
}

function fp_adv_integration_what_card($items){
    echo '<div class="fp-int-what-card"><h3>What this does</h3><ul>';foreach((array)$items as $item)echo '<li>'.wp_kses_post($item).'</li>';echo '</ul></div>';
}

function fp_adv_integration_steps_card($steps,$test=''){
    echo '<div class="fp-int-steps-card"><div class="fp-int-section-label">SETUP GUIDE</div><h3>Follow these steps</h3><div class="fp-int-step-list">';
    $n=0;foreach((array)$steps as $step){$n++;$allowed=['a'=>['href'=>true,'target'=>true,'rel'=>true],'code'=>[],'strong'=>[]];echo '<div class="fp-int-step"><span class="fp-int-step-number">'.(int)$n.'</span><div><strong>'.wp_kses($step,$allowed).'</strong></div></div>';}
    echo '</div>';if($test)echo '<div class="fp-int-test-box"><strong>End-to-end test</strong><p>'.wp_kses_post($test).'</p></div>';echo '</div>';
}

function fp_adv_render_provider_form($provider,$d,$cfg,$connected){
    echo '<div class="fp-int-form-card"><div class="fp-int-section-label">CONNECTION DETAILS</div><h3>Enter your '.$d['name'].' credentials</h3><p class="fp-int-form-lead">Save the credentials first, then use <strong>Test connection</strong> to verify the provider before publishing an Event Type.</p>';
    echo '<form method="post">'.wp_nonce_field('fp_integrations_save','_wpnonce',true,false).'<input type="hidden" name="fp_integration_save" value="1"><input type="hidden" name="fp_provider" value="'.esc_attr($provider).'">';
    echo '<div class="fp-field-grid fp-int-field-grid">';
    foreach($d['fields'] as $key=>$field){$val=$cfg[$key]??'';$display=$field['secret']&&$val?'':'value="'.esc_attr($val).'"';echo '<label><span>'.esc_html($field['label']).($field['required']?' <em>*</em>':'').'</span><input type="'.esc_attr($field['type']).'" name="fp_'.esc_attr($provider).'_'.esc_attr($key).'" '.$display.' autocomplete="new-password"><small>'.esc_html($field['help']).'</small></label>';}
    echo '</div><div class="fp-int-actions"><label class="fp-switch"><input type="checkbox" name="fp_'.esc_attr($provider).'_active" value="1" '.checked($connected,true,false).'><span></span> Enable</label><button class="button button-primary">Save connection</button><button type="button" class="button fp-test-btn" data-provider="'.esc_attr($provider).'">Test connection</button><span class="fp-test-result" aria-live="polite"></span></div></form>';
    echo '<div class="fp-int-security"><strong>Security</strong><span>Credentials stay on your WordPress server and are never exposed on public booking pages.</span></div></div>';
}

function fp_adv_provider_page($provider){
    if(!fp_sched_gate('core'))return;
    $defs=fp_adv_integration_configs(); if(empty($defs[$provider]))return;
    if(isset($_POST['fp_integration_save'])&&check_admin_referer('fp_integrations_save')&&sanitize_key($_POST['fp_provider']??'')===$provider){fp_adv_save_integration($provider,$defs[$provider]['fields']);echo '<div class="notice notice-success is-dismissible"><p><strong>'.esc_html($defs[$provider]['name']).'</strong> connection settings saved.</p></div>';}
    $d=$defs[$provider];$cfg=fp_adv_masked_integration($provider);$connected=!!fp_adv_integration(get_current_user_id(),$provider);$g=fp_adv_integration_setup_data($provider);
    fp_sched_header($d['name'].' Integration');
    echo '<div class="fp-integration-page">';
    echo '<div class="fp-int-hero-simple"><div><div class="fp-eyebrow">FORMPILOT PRO · INTEGRATION</div><h2>'.esc_html($d['name']).'</h2><p>'.esc_html($d['description']).'</p></div><span class="fp-int-provider-badge">'.esc_html(fp_adv_integration_icon($provider)).'</span></div>';
    echo '<div class="fp-int-top-grid">';
    fp_adv_integration_status_card($connected,$d['name'],$connected?'Connection is active. FormPilot can use this provider for new bookings.':'Complete the setup below to enable '.$d['name'].' sync and automation.');
    $what=[];if(!empty($g['purpose']))$what[]=$g['purpose'];$what[]='Bookings flow through FormPilot and update the connected service when the relevant Event Type is used.';if(in_array($provider,['zoom','teams'],true))$what[]='Creates a provider meeting link automatically for supported Event Type locations.';if(in_array($provider,['hubspot','salesforce'],true))$what[]='Creates or updates the customer contact after a booking.';fp_adv_integration_what_card($what);
    echo '</div>';
    if(!$connected){fp_adv_integration_steps_card($g['steps']??[],$g['test']??'');}
    else {echo '<div class="fp-int-connected-note"><strong>Connection ready.</strong><span>Run Test connection below after any credential change, then use this provider on an Event Type.</span></div>';$test=$g['test']??'';if($test)echo '<div class="fp-int-test-box fp-int-test-box-wide"><strong>Recommended verification</strong><p>'.esc_html($test).'</p></div>';}
    fp_adv_render_provider_form($provider,$d,$cfg,$connected);
    echo '<div class="fp-int-after-card"><div><div class="fp-int-section-label">AFTER CONNECTION</div><h3>What happens when a customer books?</h3></div><div class="fp-int-flow"><span>Customer books</span><b>→</b><span>FormPilot processes booking</span><b>→</b><span>'.esc_html($d['name']).' is called</span><b>→</b><span>Confirmation is sent</span></div></div>';
    echo '</div>';fp_sched_footer();
}

function fp_adv_google_integration_page(){
    if(!fp_sched_gate('core'))return;
    if(isset($_POST['fp_google_save'])&&check_admin_referer('fp_google_dedicated')){update_option('ssb_google_client_id',sanitize_text_field($_POST['ssb_google_client_id']??''));update_option('ssb_google_client_secret',sanitize_text_field($_POST['ssb_google_client_secret']??''));update_option('ssb_google_calendar_id',sanitize_text_field($_POST['ssb_google_calendar_id']??'primary'));update_option('ssb_google_timezone',sanitize_text_field($_POST['ssb_google_timezone']??'America/New_York'));update_option('ssb_google_meet_enabled',isset($_POST['ssb_google_meet_enabled'])?'1':'0');echo '<div class="notice notice-success is-dismissible"><p><strong>Google Calendar</strong> settings saved.</p></div>';}
    $connected=function_exists('ssb_google_is_connected')&&ssb_google_is_connected();$auth_url=function_exists('ssb_google_get_auth_url')?ssb_google_get_auth_url():false;
    fp_sched_header('Google Calendar Integration');
    $oauth_msg=sanitize_key($_GET['ssb_msg']??'');$oauth_err=sanitize_text_field($_GET['ssb_err']??'');
    if($oauth_msg==='connected')echo '<div class="notice notice-success is-dismissible"><p><strong>Google Calendar connected successfully.</strong> Run Test connection below before using it on live Event Types.</p></div>';
    elseif($oauth_msg==='disconnected')echo '<div class="notice notice-info is-dismissible"><p>Google Calendar disconnected.</p></div>';
