    fp_adv_integration_status_card($connected,'Google Calendar',$connected?'Calendar sync is active. Calendar ID: <strong>'.esc_html(get_option('ssb_google_calendar_id','primary')).'</strong> · Google Meet: <strong>'.(get_option('ssb_google_meet_enabled','1')==='1'?'Enabled':'Disabled').'</strong>':'Complete the setup below to enable calendar sync and automatic Google Meet links.');
    fp_adv_integration_what_card(['Automatically creates a Google Calendar event for every booking.','Checks connected calendar busy time before offering slots.','Generates a Google Meet link when enabled.','Includes meeting details in the customer confirmation.','Invites the customer to the calendar event and adds reminders.']);
    echo '</div>';
    if(!$connected){$steps=['Create or choose a Google Cloud project and enable the Google Calendar API.','Configure the OAuth consent screen and add your Google account as a test user if the app is in testing.','Create OAuth 2.0 credentials for a Web application.','Add this exact Authorized Redirect URI to the OAuth client: '.ssb_google_redirect_uri(),'Copy the Client ID and Client Secret into FormPilot, save, then click Connect to Google Calendar.'];fp_adv_integration_steps_card($steps,'Create a private test Event Type using Google Meet, book it, and confirm the event appears on the connected calendar.');}
    echo '<div class="fp-int-form-card"><div class="fp-int-section-label">CONNECTION DETAILS</div><h3>Enter your Google Calendar credentials</h3><p class="fp-int-form-lead">Your OAuth client is used only to authorize FormPilot to access the selected calendar.</p><form method="post">'.wp_nonce_field('fp_google_dedicated','_wpnonce',true,false).'<input type="hidden" name="fp_google_save" value="1"><div class="fp-field-grid fp-int-field-grid">';
    $fields=[['id'=>'ssb_google_client_id','label'=>'Client ID','type'=>'text','value'=>get_option('ssb_google_client_id',''),'help'=>'From Google Cloud → APIs & Services → Credentials.'],['id'=>'ssb_google_client_secret','label'=>'Client Secret','type'=>'password','value'=>get_option('ssb_google_client_secret',''),'help'=>'Keep this secret and do not share it publicly.'],['id'=>'ssb_google_calendar_id','label'=>'Calendar ID','type'=>'text','value'=>get_option('ssb_google_calendar_id','primary'),'help'=>'Use primary for the main calendar, or paste another Calendar ID.']];foreach($fields as $f){echo '<label><span>'.esc_html($f['label']).'</span><input type="'.esc_attr($f['type']).'" name="'.esc_attr($f['id']).'" value="'.esc_attr($f['value']).'" autocomplete="new-password"><small>'.esc_html($f['help']).'</small></label>';}
    echo '<label><span>Event Timezone</span><select name="ssb_google_timezone">';$tz_list=['America/New_York'=>'Eastern (ET)','America/Chicago'=>'Central (CT)','America/Denver'=>'Mountain (MT)','America/Los_Angeles'=>'Pacific (PT)','Europe/London'=>'London (GMT/BST)','Europe/Paris'=>'Paris (CET)','Europe/Berlin'=>'Berlin (CET)','Asia/Karachi'=>'Karachi (PKT)','Asia/Kolkata'=>'India (IST)','Asia/Dubai'=>'Dubai (GST)','Asia/Singapore'=>'Singapore (SGT)','Asia/Tokyo'=>'Tokyo (JST)','Australia/Sydney'=>'Sydney (AEST)','UTC'=>'UTC'];$tz_saved=get_option('ssb_google_timezone','America/New_York');foreach($tz_list as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($tz_saved,$v,false).'>'.esc_html($l).'</option>';echo '</select><small>Timezone used when FormPilot creates calendar events.</small></label>';
    echo '</div><div class="fp-int-option-row"><label class="fp-switch"><input type="checkbox" name="ssb_google_meet_enabled" value="1" '.checked(get_option('ssb_google_meet_enabled','1'),'1',false).'><span></span> Automatically generate Google Meet links</label></div><div class="fp-int-actions"><button class="button button-primary">Save Google settings</button>';if($auth_url){echo '<a href="'.esc_url($auth_url).'" class="button fp-google-connect-btn">'.esc_html($connected?'Re-authorize Google Calendar':'Connect to Google Calendar').'</a>';if($connected){echo '<a href="'.esc_url(wp_nonce_url(admin_url('admin.php?page=fp-integration-google&ssb_google_callback=1&ssb_google_disconnect=1'),'ssb_google_disconnect')).'" class="button" onclick="return confirm(\'Disconnect Google Calendar?\')">Disconnect</a>';}}echo '<button type="button" class="button fp-test-btn" data-provider="google">Test connection</button><span class="fp-test-result" aria-live="polite"></span></div></form><div class="fp-int-security"><strong>Security</strong><span>OAuth tokens remain server-side. Public booking pages never receive your Google credentials.</span></div></div>';
    echo '<div class="fp-int-after-card"><div><div class="fp-int-section-label">AFTER CONNECTION</div><h3>Booking flow</h3></div><div class="fp-int-flow"><span>Customer books</span><b>→</b><span>Availability checked</span><b>→</b><span>Calendar event + Meet</span><b>→</b><span>Confirmation sent</span></div></div></div>';fp_sched_footer();
}

function fp_adv_stripe_integration_page(){
    if(!fp_sched_gate('core'))return;
    if(isset($_POST['fp_stripe_save'])&&check_admin_referer('fp_stripe_dedicated')){update_option('ssb_payment_enabled',isset($_POST['ssb_payment_enabled'])?'1':'0');update_option('ssb_stripe_publishable_key',sanitize_text_field($_POST['ssb_stripe_publishable_key']??''));update_option('ssb_stripe_secret_key',sanitize_text_field($_POST['ssb_stripe_secret_key']??''));update_option('ssb_stripe_test_mode',isset($_POST['ssb_stripe_test_mode'])?'1':'0');update_option('ssb_booking_price',sanitize_text_field($_POST['ssb_booking_price']??'0'));update_option('ssb_booking_currency',sanitize_text_field($_POST['ssb_booking_currency']??'USD'));update_option('ssb_payment_description',sanitize_text_field($_POST['ssb_payment_description']??'Booking payment'));echo '<div class="notice notice-success is-dismissible"><p><strong>Stripe</strong> settings saved.</p></div>';}
    $key=(string)get_option('ssb_stripe_secret_key','');$connected=!empty($key);$test_mode=get_option('ssb_stripe_test_mode','1')==='1';
    fp_sched_header('Stripe Integration');echo '<div class="fp-integration-page">';
    echo '<div class="fp-int-hero-simple"><div><div class="fp-eyebrow">FORMPILOT PRO · INTEGRATION</div><h2>Stripe Payments</h2><p>Accept payments for paid Event Types, verify PaymentIntents server-side and generate invoices after successful payment.</p></div><span class="fp-int-provider-badge">S</span></div><div class="fp-int-top-grid">';
    fp_adv_integration_status_card($connected,'Stripe',$connected?'Stripe credentials are saved. Current mode: <strong>'.esc_html($test_mode?'Test mode':'Live mode').'</strong>.':'Add your Stripe API keys below. Test mode is recommended until your complete payment flow is verified.');
    fp_adv_integration_what_card(['Accepts card payments before a paid booking is confirmed.','Verifies the PaymentIntent on the server before accepting the booking.','Supports paid Event Types with their own amount and currency.','Creates an invoice after a successful paid booking.','Keeps secret API keys on the server; public forms only use the publishable key.']);
    echo '</div>';
    if(!$connected)fp_adv_integration_steps_card(['Open Stripe Dashboard and keep Test mode enabled while configuring FormPilot.','Copy the Publishable key and Secret key from Developers → API keys.','Paste both keys below and keep Test mode enabled.','Create a paid Event Type with an amount and currency.','Run a complete test checkout before switching to live mode.'],'Use Stripe test mode, complete a paid booking, then confirm the PaymentIntent succeeds, the booking is confirmed and an invoice appears under FormPilot Pro → Invoices.');
    echo '<div class="fp-int-form-card"><div class="fp-int-section-label">CONNECTION DETAILS</div><h3>Enter your Stripe credentials</h3><p class="fp-int-form-lead">Use test keys first. Do not switch to live mode until a full booking, payment and invoice test passes.</p><form method="post">'.wp_nonce_field('fp_stripe_dedicated','_wpnonce',true,false).'<input type="hidden" name="fp_stripe_save" value="1"><div class="fp-field-grid fp-int-field-grid">';
    $stripe_fields=[['id'=>'ssb_stripe_publishable_key','label'=>'Publishable Key','type'=>'text','value'=>get_option('ssb_stripe_publishable_key',''),'help'=>'Starts with pk_test_ or pk_live_.'],['id'=>'ssb_stripe_secret_key','label'=>'Secret Key','type'=>'password','value'=>get_option('ssb_stripe_secret_key',''),'help'=>'Starts with sk_test_ or sk_live_. Keep it private.'],['id'=>'ssb_booking_price','label'=>'Default Booking Price','type'=>'number','value'=>get_option('ssb_booking_price','0'),'help'=>'Legacy/default amount. Paid Event Types can define their own price.'],['id'=>'ssb_payment_description','label'=>'Payment Description','type'=>'text','value'=>get_option('ssb_payment_description','Booking payment'),'help'=>'Shown in Stripe as the payment description.']];foreach($stripe_fields as $f){echo '<label><span>'.esc_html($f['label']).'</span><input type="'.esc_attr($f['type']).'" name="'.esc_attr($f['id']).'" value="'.esc_attr($f['value']).'" autocomplete="new-password"><small>'.esc_html($f['help']).'</small></label>';}
    echo '<label><span>Currency</span><select name="ssb_booking_currency">';$currencies=['USD'=>'USD — US Dollar','EUR'=>'EUR — Euro','GBP'=>'GBP — British Pound','CAD'=>'CAD — Canadian Dollar','AUD'=>'AUD — Australian Dollar','PKR'=>'PKR — Pakistani Rupee','INR'=>'INR — Indian Rupee','SGD'=>'SGD — Singapore Dollar','AED'=>'AED — UAE Dirham'];$saved_curr=get_option('ssb_booking_currency','USD');foreach($currencies as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($saved_curr,$v,false).'>'.esc_html($l).'</option>';echo '</select><small>Used for the legacy/default booking payment settings.</small></label>';
    echo '</div><div class="fp-int-option-grid"><label class="fp-switch"><input type="checkbox" name="ssb_payment_enabled" value="1" '.checked(get_option('ssb_payment_enabled','0'),'1',false).'><span></span> Enable payments</label><label class="fp-switch"><input type="checkbox" name="ssb_stripe_test_mode" value="1" '.checked($test_mode,true,false).'><span></span> Use Stripe test mode</label></div><div class="fp-int-actions"><button class="button button-primary">Save Stripe settings</button><button type="button" class="button fp-test-btn" data-provider="stripe">Test connection</button><span class="fp-test-result" aria-live="polite"></span></div></form><div class="fp-int-security"><strong>Security</strong><span>Stripe secret keys stay server-side. FormPilot verifies payments against Stripe before creating paid bookings.</span></div></div>';
    echo '<div class="fp-int-after-card"><div><div class="fp-int-section-label">AFTER CONNECTION</div><h3>Payment flow</h3></div><div class="fp-int-flow"><span>Customer selects paid event</span><b>→</b><span>Stripe checkout</span><b>→</b><span>PaymentIntent verified</span><b>→</b><span>Booking + invoice</span></div></div></div>';fp_sched_footer();
}

