      ['title'=>'Create → Publish → Book','desc'=>'See the complete one-on-one flow from Event Type creation to a real public booking.','steps'=>['Create a 30-minute Consultation.','Set Monday–Friday availability.','Choose Google Meet or Zoom.','Copy the public link and book it in a private browser.','Open the confirmation and manage-booking link.'],'url'=>admin_url('admin.php?page=fp-scheduling')],
      ['title'=>'Paid event → Stripe → Invoice','desc'=>'See how a paid booking becomes a verified payment and an invoice.','steps'=>['Connect Stripe in its dedicated settings page.','Create a paid Event Type, for example USD 99.','Run a Stripe test-mode booking.','FormPilot verifies the PaymentIntent before creating the booking.','The invoice appears under Invoices with a print/save-as-PDF view.'],'url'=>admin_url('admin.php?page=fp-integration-stripe')],
      ['title'=>'Zoom / Teams meeting creation','desc'=>'Connect a provider, assign it to an Event Type and let FormPilot create the meeting automatically.','steps'=>['Connect the provider and run Test connection.','Set the Event Type location to Zoom or Teams.','Book from a private browser.','Open the booking and confirmation email.','Verify the provider-generated join URL.'],'url'=>admin_url('admin.php?page=fp-integrations')],
      ['title'=>'CRM sync','desc'=>'Bookings create or update contacts in HubSpot and Salesforce.','steps'=>['Connect the CRM from its dedicated integration page.','Run Test connection.','Create a test booking with a new email.','Confirm the contact appears in the CRM.','Book again with the same email to test update behavior.'],'url'=>admin_url('admin.php?page=fp-integration-hubspot')],
      ['title'=>'Invoice workflow','desc'=>'Understand exactly where invoices come from and how customers receive them.','steps'=>['Use a paid Event Type.','Complete successful payment.','FormPilot creates the invoice automatically.','Open FormPilot → Invoices.','Use View / Print to save a PDF from the browser.'],'url'=>admin_url('admin.php?page=fp-invoices')],
      ['title'=>'Round robin / group / collective','desc'=>'Use the real scheduling engine for team and capacity-based events.','steps'=>['Create host users or a host pool.','Create the appropriate event type.','Configure availability.','Run several test bookings.','Review assigned hosts and remaining group seats.'],'url'=>admin_url('admin.php?page=fp-scheduling')],
    ];
    echo '<div class="fp-demo-grid">';foreach($demos as $d){echo '<article class="fp-demo-card"><div class="fp-card-kicker">LIVE EXAMPLE</div><h2>'.esc_html($d['title']).'</h2><p>'.esc_html($d['desc']).'</p><ol>';foreach($d['steps'] as $st)echo '<li>'.esc_html($st).'</li>';echo '</ol><a class="button button-primary" href="'.esc_url($d['url']).'">Open this area →</a></article>';}echo '</div>';fp_sched_footer();
