/* Invoice UX: make generated invoices obvious and printable. */
add_action('admin_init',function(){
    if(!is_admin()||empty($_GET['page'])||$_GET['page']!=='fp-invoices'||empty($_GET['create_invoice']))return;
    if(!current_user_can('manage_options')||!check_admin_referer('fp_create_invoice'))return;
    $id=absint($_GET['create_invoice']);$a=fp_adv_tables();$t=fp_sched_tables();global $wpdb;
    $b=$wpdb->get_row($wpdb->prepare("SELECT b.* FROM {$t['bookings']} b JOIN {$t['events']} e ON e.id=b.event_id WHERE b.id=%d AND e.user_id=%d",$id,get_current_user_id()));
    if($b&&!empty($b->payment_amount)){fp_adv_create_invoice($id,$b->payment_intent_id??'');wp_safe_redirect(admin_url('admin.php?page=fp-invoices&created=1'));exit;}
});
